function Dashboard({stats,bets,houses,houseBalances=[],currency}){const[house,setHouse]=useState(''),[period,setPeriod]=useState('month');const d=new Date(),from=period==='week'?new Date(d.getTime()-6*86400000):period==='month'?new Date(d.getTime()-29*86400000):null;const filtered=bets.filter(x=>(!house||String(x.house_id)===house)&&(!from||String(x.datetime||'').slice(0,10)>=from.toISOString().slice(0,10))&&x.result!=='pending').slice().sort((a,b)=>String(a.datetime||'').localeCompare(String(b.datetime||'')));const stake=filtered.reduce((a,x)=>a+Number(x.stake||0),0),pnl=filtered.reduce((a,x)=>a+Number(x.profit||0),0),wins=filtered.filter(x=>x.result==='win').length;let running=0;const evolution=filtered.map((x,i)=>{running+=Number(x.profit||0);return {i:i+1,p:running,date:String(x.datetime||'').slice(0,10),profit:Number(x.profit||0)}});const trend=pnl>0?'positive':pnl<0?'negative':'neutral';const selectedBalance=house?Number((houseBalances.find(x=>String(x.id)===String(house))||{}).balance||0):Number(stats.balance||0);return <div className={'dashboard-page '+trend}><div className="dashboard-head"><div><div className="dashboard-title-row"><h1>Dashboard</h1><span className="app-version">v{appPackage.version}</span></div><span className="muted">Visão geral da tua banca e desempenho</span></div><div className="filters"><select value={period} onChange={e=>setPeriod(e.target.value)}><option value="week">Últimos 7 dias</option><option value="month">Últimos 30 dias</option><option value="all">Tudo</option></select><select value={house} onChange={e=>setHouse(e.target.value)}><option value="">Todas as casas</option>{houses.map(h=><option key={h.id} value={h.id}>{h.name}</option>)}</select></div></div><div className="cards"><div className="card accent"><small>Saldo total</small><strong>{money(selectedBalance,currency)}</strong></div><div className={'card trend-card '+trend}><small>P&amp;L no período</small><strong>{money(pnl,currency)}</strong><span className="trend-label">{pnl>0?'↗ Evolução positiva':pnl<0?'↘ Evolução negativa':'→ Sem variação'}</span></div><div className={'card '+trend}><small>ROI</small><strong>{(stake?pnl/stake*100:0).toFixed(2)}%</strong></div><div className="card"><small>Win rate</small><strong>{(filtered.length?wins/filtered.length*100:0).toFixed(1)}%</strong></div><div className="card"><small>Apostas</small><strong>{filtered.length}</strong></div><div className="card"><small>Stake</small><strong>{money(stake,currency)}</strong></div></div><section><div className="section-head"><div><h2>Evolução do P&amp;L</h2><span className="muted">P&amp;L acumulado no período selecionado</span></div><span className={'trend-pill '+trend}>{pnl>0?'Positivo':pnl<0?'Negativo':'Neutro'}</span></div><div className="chart"><ResponsiveContainer><LineChart data={evolution}><XAxis dataKey="i"/><YAxis/><Tooltip formatter={(v)=>[money(v,currency),'P&amp;L acumulado']}/><Line type="monotone" dataKey="p" stroke={pnl>0?'#16a34a':pnl<0?'#dc2626':'#64748b'} strokeWidth={3} dot={false}/></LineChart></ResponsiveContainer></div></section></div>}function SearchPicker({label,value,onChange,options=[],placeholder="Pesquisar…",renderOption,renderSelected}){const[open,setOpen]=useState(false);const q=String(value||'').trim().toLowerCase();const filtered=options.filter(o=>String(o.search||o.label||'').toLowerCase().includes(q)).slice(0,30);const selected=options.find(o=>String(o.value)===String(value));return <label className="search-picker">{label}<div className="search-picker-wrap"><div className="search-picker-input-row">{selected&&renderSelected?renderSelected(selected):null}<input value={selected?.label||value||''} onFocus={()=>setOpen(true)} onChange={e=>{onChange(e.target.value);setOpen(true)}} onBlur={()=>setTimeout(()=>setOpen(false),180)} placeholder={placeholder}/></div>{open&&<div className="search-picker-menu">{filtered.length?filtered.map(o=><button type="button" key={String(o.value)} onMouseDown={e=>e.preventDefault()} onClick={()=>{onChange(o.value);setOpen(false)}}>{renderOption?renderOption(o):<span>{o.label}</span>}</button>):<div className="search-picker-empty">Nenhum resultado.</div>}</div>}</div></label>}

function CountryField({countries,x,f}){const countryName=c=>c.code?new Intl.DisplayNames(['pt-PT'],{type:'region'}).of(c.code)||c.name:c.name;const options=countries.slice().sort((a,b)=>ptSort(countryName(a),countryName(b))).map(c=>({value:c.name,label:countryName(c),search:countryName(c)+' '+(c.code||''),country:c}));return <SearchPicker label="País" value={x.country??''} onChange={v=>f('country',v)} options={options} placeholder="Pesquisar país…" renderSelected={o=><CountryFlag country={o.country}/>} renderOption={o=><><CountryFlag country={o.country}/><span><b>{o.label}</b>{o.country.code&&<small>{o.country.code}</small>}</span></>}/>}

function CompetitionField({competitions,country,value,onChange}){const options=(competitions||[]).filter(c=>!country||String(c.country_id)===String(country.id)).slice().sort((a,b)=>ptSort(a.name,b.name)).map(c=>({value:c.name,label:c.name,search:c.name,country:c}));return <SearchPicker label="Competição" value={value??''} onChange={onChange} options={options} placeholder={country?"Pesquisar competição…":"Seleciona primeiro um país"} renderOption={o=><><span className="competition-option-icon"><Icon name="emoji_events"/></span><span><b>{o.label}</b></span></>} />}

const teamLogoFor=(team,teams=[])=>{
  if(team?.logo)return String(team.logo);
  const name=String(team?.name||'').trim();
  const base=name.replace(/\s+(?:B|II|2|U23|U-23)$/i,'').trim();
  if(!base||base.toLowerCase()===name.toLowerCase())return '';
  const senior=(teams||[]).find(t=>String(t?.name||'').trim().toLowerCase()===base.toLowerCase()&&String(t?.logo||'').trim());
  return senior?.logo?String(senior.logo):'';
};
function TeamField({label,value,onChange,teams,country,countries=[],language='pt',onSelectTeam}){
  const[open,setOpen]=useState(false),[create,setCreate]=useState(false),[busy,setBusy]=useState(false),[newTeam,setNewTeam]=useState({country:country||'',team_type:'club',logo:''});
  const normalizeSearch=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
  const q=normalizeSearch(value);
  const countryAliases={'Netherlands':'Países Baixos','The Netherlands':'Países Baixos','Nederland':'Países Baixos','England':'Inglaterra','Germany':'Alemanha','Spain':'Espanha','France':'França','Italy':'Itália','Belgium':'Bélgica','Turkey':'Turquia','Greece':'Grécia','Scotland':'Escócia','Brazil':'Brasil','Argentina':'Argentina','United States':'EUA','USA':'EUA','Portugal':'Portugal'};const normCountry=v=>{const raw=String(v||'').trim();return countryAliases[raw]||raw};const isInternational=normalizeSearch(normCountry(country))==='internacional';const matches=(teams||[]).filter(t=>(!q||normalizeSearch(teamDisplayName(t,language)).includes(q)||normalizeSearch(t.country).includes(q))&&(isInternational||!country||!t.country||normalizeSearch(normCountry(t.country))===normalizeSearch(normCountry(country))));
  const save=()=>{
    const name=String(value||'').trim();
    if(!name)return;
    setBusy(true);
    api('/teams',{method:'POST',body:JSON.stringify({name,country:newTeam.country||country||'',team_type:newTeam.team_type||'club',logo:newTeam.logo||''})}).then(t=>{onChange(t.name);onSelectTeam?.(t);setCreate(false);setOpen(false)}).catch(e=>alert(e.message)).finally(()=>setBusy(false));
  };
  const selected=(teams||[]).find(t=>t.name===value||teamDisplayName(t,language)===value);const selectedLogo=teamLogoFor(selected,teams);
  const selectedCountry=(countries||[]).find(c=>String(c.name||'').toLowerCase()===normCountry(selected?.country).toLowerCase());
  const isNational=selected?.team_type==='national'||selected?.team_type==='national_youth';
  const countryLogo=isNational?selectedCountry?.logo:'';
  const countryLogoNode=countryLogo?(String(countryLogo).startsWith('http')?<img className="team-input-logo team-country-image" src={countryLogo} alt="" />:<span className="team-input-logo team-country-logo" aria-label={selected?.country||''}>{countryLogo}</span>):null;
  return <label className="team-field">{label}<div style={{position:'relative'}}>
    <div className="team-input-row">
      {selectedLogo?<img className="team-input-logo" src={selectedLogo} alt="" />:countryLogoNode}
      <input value={value||''} onFocus={()=>setOpen(true)} onChange={e=>{onChange(e.target.value);setOpen(true)}} onBlur={()=>setTimeout(()=>setOpen(false),180)} placeholder="Pesquisar equipa…"/>
    </div>
    {selected&&<div className="team-selected-meta"><span>País: <b>{selected.country||'Sem país'}</b></span><span>Logo: {selectedLogo||countryLogo?'disponível':'não disponível'}</span></div>}
    {open&&<div className="team-suggestions">
      {matches.map(t=>{
        const c=(countries||[]).find(v=>String(v.name||'').toLowerCase()===normCountry(t.country).toLowerCase());
        const tLogo=teamLogoFor(t,teams);
        const isNat=t.team_type==='national'||t.team_type==='national_youth';
        return <button type="button" key={t.id} onMouseDown={e=>e.preventDefault()} onClick={()=>{onChange(t.name);onSelectTeam?.(t);setOpen(false)}}>{tLogo?<img src={tLogo} alt="" />:isNat&&c?.logo?(String(c.logo).startsWith('http')?<img src={c.logo} alt="" className="team-suggestion-country"/>:<span className="team-suggestion-country">{c.logo}</span>):<span className="team-suggestion-ball">⚽</span>}<span><b>{teamDisplayName(t,language)}</b><small>{t.country||'Sem país'} · {t.team_type==='national_youth'?'Seleção jovem':t.team_type==='national'?'Seleção':'Clube'}</small></span></button>
      })}
      <button type="button" className="team-create" onMouseDown={e=>e.preventDefault()} onClick={()=>setCreate(true)}>＋ Criar equipa{q?' “'+value+'”':''}</button>
      {create&&<div className="team-create-form"><input value={value||''} onChange={e=>onChange(e.target.value)} placeholder="Nome da equipa"/><label>País<select value={newTeam.country} onChange={e=>setNewTeam({...newTeam,country:e.target.value})}><option value="">Sem país</option>{countries.slice().sort((a,b)=>ptSort(a.name,b.name)).map(c=><option key={c.id} value={c.name}>{c.logo?c.logo+' ':''}{c.name}</option>)}</select></label><label>Tipo<select value={newTeam.team_type} onChange={e=>setNewTeam({...newTeam,team_type:e.target.value})}><option value="club">Clube</option><option value="club_reserve">Equipa B/Reserva</option><option value="national">Seleção</option><option value="national_youth">Seleção jovem</option><option value="women">Equipa feminina</option></select></label><label>Logo (URL)<input value={newTeam.logo} onChange={e=>setNewTeam({...newTeam,logo:e.target.value})} placeholder="https://…/logo.png"/></label><button type="button" className="primary" onClick={save} disabled={busy}>{busy?'A criar…':'Criar e selecionar'}</button></div>}
    </div>}
  </div></label>
}
function TeamManager({teams,done,countries=[],language='pt'}){const[q,setQ]=useState(''),[country,setCountry]=useState(''),[page,setPage]=useState(1),[online,setOnline]=useState([]),[busy,setBusy]=useState(false);const allRows=teams||[];const countryOptions=[...new Set(allRows.map(t=>String(t.country||'').trim()).filter(Boolean))].sort(ptSort);useEffect(()=>setPage(1),[q,country]);const term=q.trim().toLowerCase();const filtered=allRows.filter(t=>(!term||teamDisplayName(t,language).toLowerCase().includes(term)||String(t.name||'').toLowerCase().includes(term)||String(t.country||'').toLowerCase().includes(term))&&(!country||String(t.country||'').toLowerCase()===country.toLowerCase())).sort((a,b)=>ptSort(teamDisplayName(a,language),teamDisplayName(b,language)));const perPage=25,totalPages=Math.max(1,Math.ceil(filtered.length/perPage)),currentPage=Math.min(page,totalPages),visible=filtered.slice((currentPage-1)*perPage,currentPage*perPage);const search=()=>{const p=q.trim();if(!p)return setOnline([]);setBusy(true);api('/teams/search?q='+encodeURIComponent(p)).then(setOnline).catch(e=>alert(e.message)).finally(()=>setBusy(false))};const add=t=>api('/teams',{method:'POST',body:JSON.stringify(t)}).then(()=>{setOnline([]);done?.()}).catch(e=>alert(e.message));const create=()=>{const name=q.trim();if(!name)return;add({name,country:'',team_type:'club',source:'manual'});setQ('')};return <section><div className="section-head"><div><h1>Equipas</h1><span className="muted">{allRows.length} equipas no catálogo</span></div><button className="primary" onClick={()=>{setBusy(true);api('/teams/seed-all',{method:'POST'}).then(r=>{alert((r.count||0)+' registos processados. Catálogo: '+(r.total||0)+' equipas.');return done?.()}).catch(e=>alert(e.message)).finally(()=>setBusy(false))}} disabled={busy}><Icon name="download"/> {busy?'A atualizar…':'Atualizar catálogo'}</button></div><div style={{display:'flex',gap:8,marginBottom:18,flexWrap:'wrap'}}><input style={{flex:1,minWidth:240}} value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&search()} placeholder="Pesquisar equipa…"/><select value={country} onChange={e=>setCountry(e.target.value)} style={{minWidth:220}}><option value="">Todos os países</option>{countryOptions.map(x=><option key={x} value={x}>{x}</option>)}</select><button className="secondary-btn" onClick={search} disabled={busy}>{busy?'A pesquisar…':'Pesquisar online'}</button><button className="primary" onClick={create} disabled={!q.trim()||busy}>＋ Criar equipa</button></div>{online.length>0&&<div className="tablewrap" style={{marginBottom:18}}><table><thead><tr><th>Logo</th><th>Equipa</th><th>País</th><th>Tipo</th><th></th></tr></thead><tbody>{online.map(t=><tr key={(t.external_id||'x')+t.name}><td>{teamLogoFor(t,allRows)?<img src={teamLogoFor(t,allRows)} alt="" style={{width:34,height:34,objectFit:'contain'}}/>:'⚽'}</td><td>{t.name}</td><td>{t.country||'—'}</td><td>{t.team_type==='national'?'Seleção':t.team_type==='national_youth'?'Seleção jovem':'Clube'}</td><td><button className="primary" onClick={()=>add(t)}>Adicionar</button></td></tr>)}</tbody></table></div>}<div className="tablewrap"><table><thead><tr><th>Logo</th><th>Equipa</th><th>País</th><th>Tipo</th></tr></thead><tbody>{visible.map(t=><tr key={t.id}><td>{teamLogoFor(t,allRows)?<img src={teamLogoFor(t,allRows)} alt="" style={{width:34,height:34,objectFit:'contain'}}/>:(()=>{const c=(countries||[]).find(v=>String(v.name||'').toLowerCase()===String(t.country||'').toLowerCase());const l=(t.team_type==='national'||t.team_type==='national_youth')?c?.logo:'';return l?(String(l).startsWith('http')?<img src={l} alt="" style={{width:34,height:34,objectFit:'contain'}}/>:<span>{l}</span>):'⚽'})()}</td><td>{teamDisplayName(t,language)}</td><td>{t.country||'—'}</td><td>{t.team_type==='national'?'Seleção nacional':t.team_type==='national_youth'?'Seleção jovem':t.team_type==='club_reserve'?'Clube B / reserva':t.team_type==='women'?'Feminina':'Clube'}</td></tr>)}</tbody></table></div><div className="section-head" style={{marginTop:12,marginBottom:0}}><span className="muted">{filtered.length} equipas · página {currentPage} de {totalPages}</span><div style={{display:'flex',gap:6}}><button className="secondary-btn" disabled={currentPage<=1} onClick={()=>setPage(p=>Math.max(1,p-1))}>← Anterior</button><button className="secondary-btn" disabled={currentPage>=totalPages} onClick={()=>setPage(p=>Math.min(totalPages,p+1))}>Seguinte →</button></div></div></section>}
function BetForm({bets=[],teams=[],houses,countries,competitions,markets,done,edit,currency,oddsFormat='dot',cancelEdit,houseBalances=[],language='pt'}){const[x,setX]=useState(edit?{...edit,selections:edit.selections||[],odds:edit.odds||'',combined_odds:edit.combined_odds||''}:{datetime:now(),odds:'',stake:'',result:'pending',bonus:false,bet_type:'single',selections:[],combined_odds:''}),[newMarket,setNewMarket]=useState(''),[marketBusy,setMarketBusy]=useState(false),[marketError,setMarketError]=useState('');const[marketOptions,setMarketOptions]=useState(markets),[saveError,setSaveError]=useState('');const f=(k,v)=>{setSaveError('');setX(a=>({...a,[k]:v}))};const changeSel=(i,k,v)=>setX(a=>({...a,selections:a.selections.map((s,j)=>j===i?{...s,[k]:v,...(k==='country'?{competition:''}:{})}:s)}));const removeSel=i=>setX(a=>({...a,selections:a.selections.filter((_,j)=>j!==i)}));const selectedCountry=countries.find(c=>c.name===x.country);const filteredComps=selectedCountry?competitions.filter(c=>Number(c.country_id)===Number(selectedCountry.id)).slice().sort((a,b)=>ptSort(a.name,b.name)):[];const addMarket=()=>{const name=newMarket.trim();if(!name)return;setMarketBusy(true);setMarketError('');api('/markets',{method:'POST',body:JSON.stringify({name})}).then(()=>api('/markets')).then(list=>{setMarketOptions(list);setNewMarket('');setX(a=>({...a,market:name}));setMarketError('');setMarketBusy(false)}).catch(e=>{setMarketError(e.message);setMarketBusy(false)})};const addEvent=()=>{if(!x.home_team||!x.away_team||!x.country||!x.competition||!x.market||x.market==='__new__'||!Number.isFinite(parseNum(x.odds))){setSaveError('Preenche o jogo, país, competição, mercado e odds antes de adicionar o evento.');return}const event={home_team:x.home_team||'',away_team:x.away_team||'',event:x.event||((x.home_team||'')+' — '+(x.away_team||'')),country:x.country,competition:x.competition,market:x.market,selection:x.selection,odds:parseNum(x.odds)};setX(a=>({...a,selections:[...(a.selections||[]),event],combined_odds:(a.selections||[]).reduce((v,s)=>v*Number(s.odds||1),1)*Number(event.odds||1),home_team:'',away_team:'',country:'',competition:'',market:'',selection:'',odds:''}));setSaveError('')};const save=()=>{setSaveError('');const first=(x.selections||[])[0]||{};const payload={...x,...(x.bet_type==='multiple'?{country:first.country||x.country,competition:first.competition||x.competition,home_team:first.home_team||x.home_team,away_team:first.away_team||x.away_team,market:first.market||x.market,selection:first.selection||x.selection,odds:parseNum(x.combined_odds||0)}:{odds:parseNum(x.odds||0)})};if(x.bet_type==='multiple'&&(!x.selections||!x.selections.length))return setSaveError('Adiciona pelo menos um evento à múltipla.');api(edit?'/bets/'+edit.id:'/bets',{method:edit?'PUT':'POST',body:JSON.stringify(payload)}).then(done).catch(e=>setSaveError(e.message))};const selectedHouse=houses.find(h=>String(h.id)===String(x.house_id));const selectedHouseBalance=houseBalances.find(h=>String(h.id)===String(x.house_id));const currentBankroll=Number(selectedHouseBalance?.balance)||0;const stakePercent=Number(selectedHouse?.stake_limit_percent);const calculatedStake=currentBankroll>0&&Number.isFinite(stakePercent)?currentBankroll*stakePercent/100:0;const stakeValue=Number(x.stake)||0;const actualStakePercent=currentBankroll>0?stakeValue/currentBankroll*100:0;const stakeExceeded=Number.isFinite(stakePercent)&&currentBankroll>0&&stakeValue>0&&actualStakePercent>stakePercent;return <section><h1>{edit?'Editar aposta':'Nova aposta'}</h1><div className="grid"><Field label="Tipo" k="bet_type" x={x} f={f} type="select" opts={[['single','Simples'],['multiple','Múltipla']]}/><Field label="Data/hora" k="datetime" x={x} f={f} type="datetime-local"/><label>Casa<div className="house-bet-select"><select value={x.house_id==null?'':String(x.house_id)} onChange={e=>f('house_id',e.target.value)}><option value="">—</option>{houses.map(h=><option key={h.id} value={String(h.id)}>{h.name}</option>)}</select>{houses.find(h=>String(h.id)===String(x.house_id))?.logo&&<img className="house-bet-logo" src={houses.find(h=>String(h.id)===String(x.house_id)).logo} alt="" />}</div></label>{x.bet_type==='multiple'&&<div className="multi-help"><b>Adicionar eventos</b><span>Preenche os campos abaixo com cada jogo e clica em “Adicionar evento”. Os eventos ficam na lista da múltipla.</span></div>}<CountryField countries={countries} x={x} f={(k,v)=>{f(k,v);if(k==='country')setX(a=>({...a,country:v,competition:''}))}}/><CompetitionField competitions={filteredComps} country={selectedCountry} value={x.competition??''} onChange={v=>f('competition',v)}/><div className="teams-matchup"><TeamField countries={countries} country={x.country} label="Equipa casa" value={x.home_team||''} onChange={v=>f('home_team',v)} teams={teams}/><div className="teams-vs" aria-hidden="true">VS</div><TeamField countries={countries} country={x.country} label="Equipa fora" value={x.away_team||''} onChange={v=>f('away_team',v)} teams={teams}/></div><Field label="Mercado" k="market" x={x} f={f} type="select" opts={[...marketOptions.map(m=>[m.name,m.name]),['__new__','＋ Adicionar novo mercado…']]}/>{x.market==='__new__'&&<div className="market-add"><input autoFocus placeholder="Nome do novo mercado" value={newMarket} onChange={e=>setNewMarket(e.target.value)}/><button type="button" onClick={addMarket} disabled={marketBusy}>{marketBusy?'A adicionar…':'Adicionar mercado'}</button>{marketError&&<span className="error">{marketError}</span>}</div>}<Field label="Seleção (opcional)" k="selection" x={x} f={f}/><Field label="Odd" k="odds" x={x} f={f} type="number"/>{x.bet_type==='multiple'&&<div className="multi-add-row"><button type="button" className="secondary-btn" onClick={addEvent}><svg className="action-svg" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 6h10M5 12h10M5 18h6"/><path d="M18 13v6M15 16h6"/></svg> Adicionar evento</button><span className="muted">{(x.selections||[]).length} {(x.selections||[]).length===1?'evento':'eventos'}</span></div>}<div className="stake-control"><Field label={`Stake ${currency}`} k="stake" x={x} f={f} type="number"/><div className="stake-limit-info">{selectedHouse?<>Limite desta casa: <b>{stakePercent.toFixed(1)}%</b> da banca · banca atual <b>{money(currentBankroll,currency)}</b>{currentBankroll>0&&<>{!edit&&<span> · stake calculada <b>{money(calculatedStake,currency)}</b></span>} · stake atual <b>{money(stakeValue,currency)} ({actualStakePercent.toFixed(2)}%)</b></>}</>:<>Seleciona uma casa para consultar o limite de stake.</>}</div>{selectedHouse&&<StakeAwareness limit={stakePercent} actual={stakeValue} bankroll={currentBankroll}/>} {stakeExceeded&&<div className="stake-warning stake-warning-alert" role="alert"><span className="material-symbols-outlined">warning</span><span>A stake de <b>{actualStakePercent.toFixed(2)}%</b> ultrapassa o limite de <b>{stakePercent.toFixed(1)}%</b> definido para esta casa. A aposta pode ser guardada, mas este valor merece atenção.</span></div>}</div><Field label="Resultado" k="result" x={x} f={f} type="select" opts={[['pending','pending'],['win','Green'],['loss','Red']]}/>{x.result!=='loss'&&Number(x.stake)>0&&Number(x.bet_type==='multiple'?x.combined_odds:x.odds)>0&&<><label>Potencial ganho {currency}<input value={((Number(x.stake)||0)*((Number(x.bet_type==='multiple'?x.combined_odds:x.odds)||0)-1)).toFixed(2)} readOnly/></label><label>Potencial ganho (%)<input value={(((Number(x.bet_type==='multiple'?x.combined_odds:x.odds)||0)-1)*100).toFixed(2)+'%'} readOnly/></label></>}<Field label="Notas" k="notes" x={x} f={f} type="textarea"/></div>{x.bet_type==='multiple'&&<div className="multi"><div className="section-head"><div><h3>Eventos da múltipla</h3><span className="muted">Podes remover um evento antes de guardar.</span></div><b>Odd combinada: {formatOdds(x.combined_odds||0,oddsFormat)}</b></div>{!(x.selections||[]).length?<div className="empty">Ainda não adicionaste nenhum evento.</div>:<div className="tablewrap"><table><thead><tr><th>#</th><th>Jogo</th><th>País</th><th>Competição</th><th>Mercado</th><th>Seleção</th><th>Odd</th><th></th></tr></thead><tbody>{(x.selections||[]).map((s,i)=><tr key={i}><td><span className="multi-event-number">{i+1}</span></td><td>{s.home_team||s.event||'—'}{s.away_team?' — '+s.away_team:''}</td><td>{s.country||'—'}</td><td>{s.competition||'—'}</td><td>{s.market||'—'}</td><td>{s.selection||'—'}</td><td>{formatOdds(s.odds,oddsFormat)}</td><td><button type="button" className="multi-event-action" onClick={()=>removeSel(i)} title="Remover evento" aria-label="Remover evento"><Icon name="close"/></button></td></tr>)}</tbody></table></div>}<input type="hidden" value={x.combined_odds||''} readOnly/></div>}<label className="check"><input type="checkbox" checked={!!x.bonus} onChange={e=>f('bonus',e.target.checked)}/> Aposta bónus</label>{saveError&&<div className="error">{saveError}</div>}<div className="form-actions"><button className="primary" onClick={save}>Guardar</button>{edit&&cancelEdit&&<button type="button" className="secondary-btn" onClick={cancelEdit}>Cancelar</button>}</div></section>}

function BetList({bets,teams,houses,countries,competitions,markets,done,currency,onAdd,oddsFormat='dot',stakeLimitPercent='0',houseBalances=[],language='pt'}){const[edit,setEdit]=useState(null);const remove=id=>{if(confirm('Eliminar esta aposta?'))api('/bets/'+id,{method:'DELETE'}).then(done).catch(e=>alert(e.message))};return <>{edit&&<Modal title="Editar aposta" onClose={()=>setEdit(null)}><BetForm bets={bets} teams={teams} houses={houses} countries={countries} competitions={competitions} markets={markets} edit={edit} currency={currency} oddsFormat={oddsFormat} stakeLimitPercent={stakeLimitPercent} houseBalances={houseBalances} done={()=>{setEdit(null);done()}} cancelEdit={()=>setEdit(null)}/></Modal>}<section><div className="section-head"><div><h1>Apostas</h1><span className="muted">Histórico das apostas registadas.</span></div><div className="section-actions"><details className="export-menu"><summary className="secondary-btn"><Icon name="download"/> Exportar</summary><div className="export-menu-pop"><button type="button" onClick={()=>exportBetsCsv(bets)} title="Exportar lista para CSV"><Icon name="download"/> CSV</button><button type="button" onClick={()=>exportBetsPdf(bets,currency,oddsFormat)} title="Exportar lista para PDF"><Icon name="picture_as_pdf"/> PDF</button></div></details><button className="primary" onClick={onAdd}>Registar aposta</button></div></div><div className="tablewrap bets-tablewrap"><table><thead><tr><th>Data</th><th></th><th>Tipo</th><th>Odd</th><th>Valor apostado</th><th>Valor ganho</th><th>Ações</th></tr></thead><tbody>{bets.map(b=>{const isMultiple=b.bet_type==='multiple';const isBonus=!!b.bonus;let selections=[];try{selections=JSON.parse(b.selections||'[]')}catch{}const resultClass=b.result==='win'?'bet-history-win':b.result==='loss'?'bet-history-loss':'bet-history-pending';return <tr key={b.id} className={resultClass}><td><div className="bet-date-cell">{(()=>{const s=String(b.datetime||'').slice(0,10);const [y,mo,d]=s.split('-');return y&&mo&&d?d+'/'+mo+'/'+y:'—'})()}</div></td><td><div className="bet-house-cell">{b.house_logo&&<img className="bet-house-logo" src={b.house_logo} alt="" />}</div></td><td><span className={'history-type '+(isBonus?'bonus':isMultiple?'multiple':'single')} title={isBonus?'Aposta bónus':isMultiple?'Múltipla — '+selections.length+' eventos':'Aposta simples'} aria-label={isBonus?'Aposta bónus':isMultiple?'Múltipla — '+selections.length+' eventos':'Aposta simples'}><svg className="history-type-svg" viewBox="0 0 24 24" aria-hidden="true">{isBonus?<><path d="M12 3v18"/><path d="M7 6h7.5a3.5 3.5 0 0 1 0 7H7h5.5a3.5 3.5 0 0 1 0 7H7"/></>:isMultiple?<><path d="M6 4v16"/><path d="M6 8h7a5 5 0 0 1 5 5v7"/><path d="M13 8l-3 3 3 3"/></>:<circle cx="12" cy="12" r="4"/>}</svg>{isMultiple&&<b>{selections.length}</b>}</span></td><td>{formatOdds(b.bet_type==='multiple'?(b.combined_odds||0):(b.odds||0),oddsFormat)}</td><td>{money(b.stake,currency)}</td><td>{b.result==='win'||b.result==='loss'?(()=>{const stake=Number(b.stake||0);const total=b.result==='win'?(b.bonus?stake:stake+Number(b.profit||0)):0;const pct=stake>0?(total-stake)/stake*100:0;return <>{money(total,currency)} <span className="bet-return-percent">({pct>=0?'+':''}{pct.toFixed(2)}%)</span></>})():'—'}</td><td className="table-actions"><button className="icon-btn edit" onClick={()=>setEdit({...b,selections})} title="Editar aposta" aria-label="Editar aposta"><ActionIcon type="edit"/></button><button className="icon-btn delete" onClick={()=>remove(b.id)} title="Remover aposta" aria-label="Remover aposta"><ActionIcon type="delete"/></button></td></tr>})}</tbody></table></div></section></>}

const stakeBand=p=>{const n=Number(p)||0;if(n<=10)return{label:'Normal',className:'stake-ok'};if(n<20)return{label:'Atenção',className:'stake-warning-band'};if(n<50)return{label:'Risco elevado',className:'stake-orange'};return{label:'Risco muito elevado',className:'stake-danger'}};
const StakeAwareness=({limit,actual,bankroll})=>{const hasActual=Number.isFinite(Number(actual))&&Number(actual)>0&&Number(bankroll)>0;const actualPct=hasActual?Number(actual)/Number(bankroll)*100:0;const band=stakeBand(actualPct);return <div className="stake-awareness"><div className="stake-awareness-title"><b>Consciência de stake</b></div><div className="stake-awareness-bands"><span className="stake-band stake-ok">0–10% · Normal</span><span className="stake-band stake-warning-band">10–20% · Atenção</span><span className="stake-band stake-orange">20–50% · Risco elevado</span><span className="stake-band stake-danger">50–100% · Risco muito elevado</span></div>{Number.isFinite(Number(limit))&&<div className="stake-limit-summary">Limite definido para esta casa: <b>{Number(limit).toFixed(1)}%</b>{hasActual&&<> · Esta aposta representa <b>{actualPct.toFixed(2)}%</b> da banca (<span className={'stake-current '+band.className}>{band.label}</span>).</>}</div>}</div>}
function HouseForm({houses,balances=[],done,currency='EUR'}){const[x,setX]=useState({bonus_weekly:false,stake_limit_percent:''}),[showForm,setShowForm]=useState(false),[edit,setEdit]=useState(null);const f=(k,v)=>setX({...x,[k]:v});const startEdit=h=>{setEdit(h.id);setShowForm(true);setX({...h,bonus_weekly:!!h.bonus_weekly,stake_limit_percent:h.stake_limit_percent??''})};const cancel=()=>{setEdit(null);setShowForm(false);setX({bonus_weekly:false,stake_limit_percent:''})};const save=()=>{const p=Number(x.stake_limit_percent);if(!String(x.name||'').trim())return alert('Indica o nome da casa de apostas.');if(!Number.isFinite(p)||p<0||p>100)return alert('Define uma percentagem da banca entre 0 e 100%.');api(edit?'/houses/'+edit:'/houses',{method:edit?'PUT':'POST',body:JSON.stringify({...x,stake_limit_percent:p})}).then(()=>{cancel();done()}).catch(e=>alert(e.message))};const remove=id=>{if(confirm('Eliminar esta casa?'))api('/houses/'+id,{method:'DELETE'}).then(done).catch(e=>alert(e.message))};const weekdays=[['segunda','Segunda-feira'],['terça','Terça-feira'],['quarta','Quarta-feira'],['quinta','Quinta-feira'],['sexta','Sexta-feira'],['sábado','Sábado'],['domingo','Domingo']];const form=<><div className="grid"><Field label="Nome" k="name" x={x} f={f}/><Field label="Utilizador" k="username" x={x} f={f}/><Field label="URL do logotipo" k="logo" x={x} f={f}/><label>Percentagem da banca por aposta (%)<input type="number" min="0" max="100" step="0.1" required value={x.stake_limit_percent??''} onChange={e=>f('stake_limit_percent',e.target.value)}/><span className="muted">Define a percentagem máxima da banca que pretendes utilizar numa aposta. O valor serve como alerta de consciência, não bloqueia a aposta.</span></label><label>Bónus Semanal?<select value={x.bonus_weekly?'1':'0'} onChange={e=>f('bonus_weekly',e.target.value==='1')}><option value="0">Não</option><option value="1">Sim</option></select></label>{x.bonus_weekly&&<Field label="Dia semana bónus" k="bonus_day" x={x} f={f} type="select" opts={weekdays}/>}<Field label="Condições" k="bonus_conditions" x={x} f={f} type="textarea"/></div><StakeAwareness limit={Number(x.stake_limit_percent)} actual={0} bankroll={0}/></>;return <><section><div className="section-head"><div><h1>Casas de apostas</h1><span className="muted">Lista das casas registadas.</span></div><button className="primary" onClick={()=>{if(showForm)cancel();else{setEdit(null);setX({bonus_weekly:false,stake_limit_percent:''});setShowForm(true)}}}>{showForm?'Fechar':'Adicionar casa'}</button></div>{showForm&&!edit&&<>{form}<button className="primary" onClick={save}>Guardar casa</button><button type="button" className="secondary-btn" onClick={cancel}>Cancelar</button></>}{edit&&<Modal title="Editar casa" onClose={cancel}>{form}<div className="form-actions"><button className="primary" onClick={save}>Guardar alterações</button><button type="button" className="secondary-btn" onClick={cancel}>Cancelar</button></div></Modal>}</section><section className="houses-section"><div className="houses-grid">{houses.map(h=>{const b=balances.find(v=>v.id===h.id)||{};return <article className="house-card" key={h.id}><div className="house-card-head"><div className="house-card-brand">{h.logo&&<img className="house-card-logo" src={h.logo} alt="" />}<div><h3>{h.name||'—'}</h3><span className="muted">{h.username||'Sem utilizador'}</span></div></div><div className="house-card-actions"><button className="icon-btn edit" type="button" onClick={()=>startEdit(h)} title="Editar casa" aria-label="Editar casa"><ActionIcon type="edit"/></button><button className="icon-btn delete" type="button" onClick={()=>remove(h.id)} title="Eliminar casa" aria-label="Eliminar casa"><ActionIcon type="delete"/></button></div></div><div className="house-card-balances"><div><span>Banca inicial</span><strong>{money(b.initial_balance||0,currency)}</strong></div><div><span>Banca atual</span><strong>{money(b.balance||0,currency)}</strong></div></div><div className="house-card-details"><div><span>Stake por aposta</span><b>{Number(h.stake_limit_percent||0).toFixed(1)}%</b></div><div><span>Bónus semanal</span><b>{h.bonus_weekly?'Sim':'Não'}</b></div><div><span>Dia</span><b>{h.bonus_weekly?(h.bonus_day||'—'):'—'}</b></div></div>{h.bonus_conditions&&<div className="house-card-conditions"><span>Condições</span><p>{h.bonus_conditions}</p></div>}</article>})}</div></section></>}
function Money({houses,tx,done,currency}){const empty={datetime:now(),status:'completed',type:'deposit',amount:0,method:'',notes:''};const[x,setX]=useState(empty),[edit,setEdit]=useState(null),[showForm,setShowForm]=useState(false),f=(k,v)=>setX(a=>({...a,[k]:v}));const fs=[['datetime','Data/hora','datetime-local'],['house_id','Casa','select',houses.map(h=>[h.id,h.name])],['type','Tipo','select',[['deposit','Depósito'],['withdrawal','Levantamento'],['bonus','Bónus'],['adjustment','Ajuste'],['other','Outro']]],['amount','Valor','number'],['method','Método'],['status','Estado'],['notes','Notas','textarea']];const remove=id=>{if(confirm('Eliminar este movimento?'))api('/transactions/'+id,{method:'DELETE'}).then(done).catch(e=>alert(e.message))};const startEdit=row=>{setEdit(row.id);setShowForm(true);setX({...row,house_id:row.house_id||'',amount:Number(row.amount||0),datetime:row.datetime||now()})};const save=()=>api(edit?'/transactions/'+edit:'/transactions',{method:edit?'PUT':'POST',body:JSON.stringify(x)}).then(()=>{setEdit(null);setShowForm(false);setX({...empty,datetime:now()});done()}).catch(e=>alert(e.message));const typeLabel={deposit:'Depósito',withdrawal:'Levantamento',bonus:'Bónus',adjustment:'Ajuste',other:'Outro'};return <><section><div className="section-head"><div><h1>Movimentos</h1><span className="muted">Histórico de movimentos da banca.</span></div><button className="primary" onClick={()=>{setEdit(null);setX({...empty,datetime:now()});setShowForm(v=>!v)}}>{showForm?'Fechar':'Registar movimento'}</button></div>{showForm&&!edit&&<><div className="grid">{fs.map(z=><Field key={z[0]} label={z[1]} k={z[0]} type={z[2]} opts={z[3]} x={x} f={f}/>)}</div><button className="primary" onClick={save}>Registar</button></>}{edit&&<Modal title="Editar movimento" onClose={()=>{setEdit(null);setShowForm(false);setX({...empty,datetime:now()})}}><div className="grid">{fs.map(z=><Field key={z[0]} label={z[1]} k={z[0]} type={z[2]} opts={z[3]} x={x} f={f}/>)}</div><div className="form-actions"><button className="primary" onClick={save}>Guardar alterações</button><button type="button" className="secondary-btn" onClick={()=>{setEdit(null);setShowForm(false);setX({...empty,datetime:now()})}}>Cancelar</button></div></Modal>}</section><section><div className="tablewrap"><table><thead><tr><th>Data</th><th>Casa</th><th>Tipo</th><th>Valor</th><th>Método</th><th>Ações</th></tr></thead><tbody>{tx.map(row=><tr key={row.id}><td>{row.datetime}</td><td>{row.house_name||'—'}</td><td>{typeLabel[row.type]||row.type}</td><td>{money(row.amount,currency)}</td><td>{row.method||'—'}</td><td className="table-actions"><button className="icon-btn edit" type="button" onClick={()=>startEdit(row)} title="Editar movimento" aria-label="Editar movimento"><ActionIcon type="edit"/></button><button className="icon-btn delete" type="button" onClick={()=>remove(row.id)} title="Remover movimento" aria-label="Remover movimento"><ActionIcon type="delete"/></button></td></tr>)}</tbody></table></div></section></>}
createRoot(document.getElementById('root')).render(<App/>);